const root=document.querySelector('#prazos-view'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),dt=v=>v?v.split('-').reverse().join('/'):'—',today=()=>new Date().toISOString().slice(0,10);
let orders=[];
const effective=r=>r.newDate||r.deliveryDate,statuses=['Aguardando entrega','Entregue','Cancelado'];
root.innerHTML=`<div class="deadline-kpis"></div><section class="panel"><h3>Controle dos prazos</h3><p class="hint">Branco: prazo normal · Azul: entrega na próxima semana · Vermelho: atrasado · Verde: entregue.</p><div class="cement-filters"><label>Fornecedor<input data-supplier type="search" placeholder="Todos"></label><label>Status<select data-status><option value="">Todos</option>${statuses.map(x=>'<option>'+x+'</option>').join('')}</select></label><label>Buscar<input data-search type="search" placeholder="Código, produto ou pedido"></label></div><div class="deadline-table"></div><p class="cement-message"></p></section>`;
const msg=root.querySelector('.cement-message');
root.querySelectorAll('[data-supplier],[data-status],[data-search]').forEach(x=>x.oninput=render);
function localDate(s){return new Date(s+'T12:00:00')}
function nextWeekRange(){const d=localDate(today()),day=(d.getDay()+6)%7,monday=new Date(d);monday.setDate(d.getDate()-day+7);const friday=new Date(monday);friday.setDate(monday.getDate()+4);return [monday.toISOString().slice(0,10),friday.toISOString().slice(0,10)]}
function cls(r){if(r.status==='Entregue')return'deadline-delivered';if(r.status==='Cancelado')return'';const d=effective(r),t=today();if(d<t)return'deadline-late';const [start,end]=nextWeekRange();return d>=start&&d<=end?'deadline-nextweek':''}
function render(){const t=today(),[nwStart,nwEnd]=nextWeekRange(),late=orders.filter(r=>r.status==='Aguardando entrega'&&effective(r)<t).length,next=orders.filter(r=>r.status==='Aguardando entrega'&&effective(r)>=nwStart&&effective(r)<=nwEnd).length,waiting=orders.filter(r=>r.status==='Aguardando entrega').length,done=orders.filter(r=>r.status==='Entregue').length;
root.querySelector('.deadline-kpis').innerHTML=`<div><strong>${late}</strong><span>Atrasados</span></div><div><strong>${next}</strong><span>Próxima semana</span></div><div><strong>${waiting}</strong><span>Aguardando entrega</span></div><div><strong>${done}</strong><span>Entregues</span></div>`;
const q=root.querySelector('[data-search]').value.toLowerCase(),sup=root.querySelector('[data-supplier]').value.toLowerCase(),st=root.querySelector('[data-status]').value,rows=orders.filter(r=>(!sup||r.supplier.toLowerCase().includes(sup))&&(!st||r.status===st)&&(!q||(r.code+' '+r.product+' '+r.purchaseOrder).toLowerCase().includes(q))).sort((a,b)=>{const ad=a.status==='Entregue',bd=b.status==='Entregue';if(ad!==bd)return ad?1:-1;return effective(a).localeCompare(effective(b))});
root.querySelector('.deadline-table').innerHTML=rows.length?'<div class="table-scroll"><table><thead><tr><th>Cód</th><th>Produto</th><th>Pedido</th><th>Contato</th><th>Fornecedor</th><th>Status</th><th>Entrega prevista</th><th>Qtde</th><th>Frete</th><th>UN</th><th>Nova data</th><th>Observação</th><th>Ação</th></tr></thead><tbody>'+rows.map(r=>'<tr class="'+cls(r)+'"><td>'+esc(r.code)+'</td><td>'+esc(r.product)+'</td><td>'+esc(r.purchaseOrder)+'</td><td>'+esc(r.contact||'—')+'</td><td>'+esc(r.supplier)+'</td><td>'+esc(r.status)+'</td><td>'+dt(r.deliveryDate)+'</td><td>'+esc(r.quantity)+'</td><td>'+esc(r.freight||'—')+'</td><td>'+esc(r.unit)+'</td><td>'+dt(r.newDate)+'</td><td>'+esc(r.notes||'—')+'</td><td>'+(r.status==='Aguardando entrega'?'<button class="deadline-confirm" data-confirm="'+r.id+'">Confirmar entrega</button>':'—')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="empty-state">Nenhum pedido cadastrado.</p>';
root.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>confirmDelivery(b.dataset.confirm))}
async function confirmDelivery(id){const r=orders.find(x=>x.id===id);if(!r)return;const input={...r,status:'Entregue',version:r.version};for(const k of ['id','version','code','product','purchaseOrder','contact','supplier','status','deliveryDate','quantity','freight','unit','newDate','notes'])if(input[k]==null)input[k]='';try{bsy(true);const res=await fetch('/api/deadlines',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(['id','version','code','product','purchaseOrder','contact','supplier','status','deliveryDate','quantity','freight','unit','newDate','notes'].map(k=>[k,input[k]])))}),j=await res.json();if(!res.ok)throw Error(j.error);msg.textContent='Entrega confirmada.';await refresh()}catch(e){msg.textContent=e.message}finally{bsy(false)}}
function bsy(on){root.querySelectorAll('[data-confirm]').forEach(b=>b.disabled=on)}
async function refresh(){const r=await fetch('/api/deadlines'),j=await r.json();if(!r.ok)throw Error(j.error);orders=j.orders||[];render()}
refresh().catch(e=>msg.textContent=e.message);